def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    to_visit = {start}
    visited = set()
    parent = {}
    directions = [(-1,0), (1,0), (0,-1), (0,1)]
    found = False
    current = None
    while to_visit:
        current = to_visit.pop()
        if current in visited:
            continue
        visited.add(current)
        if current == goal:
            found = True
            break
        for dr, dc in directions:
            r, c = current[0] + dr, current[1] + dc
            if 0 <= r < rows and 0 <= c < cols:
                if grid[r][c] == '.' and (r, c) not in visited:
                    to_visit.add((r, c))
                    parent[(r, c)] = current
    if found:
        path = []
        curr = current
        while curr != start:
            curr = parent[curr]
            path.append(curr)
        path = path[::-1]
        path.append(current)
        return path
    else:
        return []

