from collections import deque

def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])
    if not (0 <= start[0] < rows and 0 <= start[1] < cols) or grid[start[0]][start[1]] == '#':
        return []
    if start == goal:
        return [start]
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols) or grid[goal[0]][goal[1]] == '#':
        return []
    queue = deque()
    queue.append(start)
    came_from = {start: None}
    directions = [(-1,0), (1,0), (0,-1), (0,1)]
    found = False
    while queue:
        current = queue.popleft()
        if current == goal:
            found = True
            break
        for dr, dc in directions:
            r = current[0] + dr
            c = current[1] + dc
            if 0 <= r < rows and 0 <= c < cols:
                if grid[r][c] == '.' and (r, c) not in came_from:
                    came_from[(r, c)] = current
                    queue.append((r, c))
    if not found:
        return []
    path = []
    current = goal
    while current is not None:
        path.append(current)
        current = came_from[current]
    return path[::-1]

