        for dx, dy in directions:
            nx, ny = current[0] + dx, current[1] + dy
            next_cell = (nx, ny)
            if 0 <= nx < rows and 0 <= ny < cols:
                if next_cell not in visited and grid[nx][ny] == '.':
                    visited.add(next_cell)
                    predecessor[next_cell] = current
                    q.append(next_cell)
    if not found:
        return []
    path = []
    current = goal
    while current != start:
        path.append(current)
        current = predecessor[current]
    path.append(start)
    path.reverse()
    return path

